insert into public.services(slug,title,summary,detail,scope,image,image_alt,sort_order) values ('grass-cutting','{"en":"Grass cutting","ar":"قص العشب"}'::jsonb,'{"en":"Mowing, edging and upkeep for an existing lawn.","ar":"قص العشب وتشذيب الحواف والعناية بالمسطح العشبي القائم."}'::jsonb,'{"en":"A clean cut starts with checking the grass type, its growth and how the area is used. Cutting height and timing can then be adjusted as heat and growth change through the season.","ar":"يبدأ القص الجيد بتحديد نوع العشب ومعدل نموه وطريقة استخدام المساحة، ثم تُضبط مواعيد القص وارتفاعه مع تغيّر الحرارة والنمو خلال الموسم."}'::jsonb,'[{"en":"Mow to a height suited to the turf.","ar":"قص العشب بارتفاع يناسب نوعه."},{"en":"Trim edges around paths and planting beds.","ar":"تشذيب الحواف حول الممرات وأحواض الزراعة."},{"en":"Clear clippings from adjacent paving.","ar":"إزالة بقايا القص عن الأرضيات المجاورة."}]'::jsonb,'villa-after','{"en":"Same courtyard with lawn and planted edges","ar":"الفناء نفسه بعد إضافة العشب والنباتات الطرفية"}'::jsonb,0);
insert into public.service_faqs(service_slug,question,answer,sort_order) values ('grass-cutting','{"en":"Can the mowing schedule change by season?","ar":"هل يتغير جدول القص حسب الموسم؟"}'::jsonb,'{"en":"Yes. Frequency can be adjusted to actual growth, turf condition and watering.","ar":"نعم، يمكن ضبط وتيرة القص وفقاً لمعدل النمو وحالة العشب والري."}'::jsonb,0);
insert into public.service_faqs(service_slug,question,answer,sort_order) values ('grass-cutting','{"en":"Does grass cutting include the planted beds?","ar":"هل يشمل قص العشب العناية بالأحواض المزروعة؟"}'::jsonb,'{"en":"Grass cutting focuses on the turf and its edges. If beds or shrubs also need attention, look at garden maintenance.","ar":"يركّز قص العشب على المسطح العشبي وحوافه. وإذا كانت الأحواض أو الشجيرات تحتاج إلى عناية أيضاً، فاطّلع على خدمة صيانة الحدائق."}'::jsonb,1);
insert into public.services(slug,title,summary,detail,scope,image,image_alt,sort_order) values ('garden-maintenance','{"en":"Garden maintenance","ar":"صيانة الحدائق"}'::jsonb,'{"en":"Pruning, tidying and seasonal care for beds, shrubs and planted areas.","ar":"تقليم وترتيب وعناية موسمية بالأحواض والشجيرات والمساحات المزروعة."}'::jsonb,'{"en":"Regular visits make it easier to spot wilting, blocked emitters and overgrown beds before small issues spread. The work can focus on high-use areas or cover the full garden.","ar":"تساعد الزيارات الدورية على رصد الذبول وانسداد النقاطات وفرط نمو النباتات قبل تفاقم المشكلات. ويمكن تركيز العمل على أكثر المساحات استخداماً أو تغطية الحديقة كاملة."}'::jsonb,'[{"en":"Light pruning and removal of dry growth.","ar":"تقليم خفيف وإزالة الأجزاء الجافة."},{"en":"Weed beds and clear fallen leaves.","ar":"إزالة الأعشاب الدخيلة والأوراق المتساقطة."},{"en":"Flag visible signs of plant stress and irrigation issues.","ar":"رصد علامات إجهاد النباتات ومشكلات الري الظاهرة."}]'::jsonb,'patio-after','{"en":"Same terrace with seating and ornamental grasses","ar":"الشرفة نفسها مع مقاعد وأعشاب للزينة"}'::jsonb,10);
insert into public.service_faqs(service_slug,question,answer,sort_order) values ('garden-maintenance','{"en":"What if I only need a one-off tidy-up?","ar":"ماذا لو احتجت إلى ترتيب الحديقة مرة واحدة فقط؟"}'::jsonb,'{"en":"Describe which areas need attention and mention any preferred date. Confirm the scope and visit options directly with TERRA when an inquiry channel is available.","ar":"حدّد المساحات التي تحتاج إلى العناية وأي موعد تفضّله. وعندما تتاح وسيلة للتواصل، أكّد نطاق العمل وخيارات الزيارة مع تيرا."}'::jsonb,0);
insert into public.service_faqs(service_slug,question,answer,sort_order) values ('garden-maintenance','{"en":"What if some plants look unhealthy?","ar":"ماذا لو بدت بعض النباتات غير سليمة؟"}'::jsonb,'{"en":"Note which plants are affected, when the signs appeared and whether watering changed. Photos can help describe what you see.","ar":"اذكر النباتات المتأثرة ومتى ظهرت العلامات وما إذا تغيّر الري. وقد تساعد الصور على وصف ما تلاحظه."}'::jsonb,1);
insert into public.services(slug,title,summary,detail,scope,image,image_alt,sort_order) values ('landscaping','{"en":"Landscaping","ar":"تنسيق المساحات الخارجية"}'::jsonb,'{"en":"Improve how an outdoor space looks and works through layout and planting.","ar":"تحسين شكل المساحة الخارجية وطريقة استخدامها من خلال التخطيط والزراعة."}'::jsonb,'{"en":"A layout starts with the routes people actually take and the places they want to spend time. Shade, screening and planting can then work together around those uses.","ar":"يبدأ التخطيط بمسارات الحركة الفعلية والأماكن التي يفضّل الناس قضاء الوقت فيها. ثم يُنسّق الظل والحجب والزراعة بما يلائم هذه الاستخدامات."}'::jsonb,'[{"en":"Review access, existing plants and shade.","ar":"مراجعة المداخل والنباتات القائمة ومناطق الظل."},{"en":"Plan paths, seating zones and planting beds.","ar":"تخطيط الممرات والجلسات وأحواض الزراعة."},{"en":"Identify materials and planting suited to site conditions.","ar":"اختيار المواد والنباتات الملائمة لظروف الموقع."}]'::jsonb,'hero','{"en":"Sunlit path through palms and grasses beside a limestone villa","ar":"ممر مشمس بين النخيل والأعشاب بجوار فيلا حجرية"}'::jsonb,20);
insert into public.service_faqs(service_slug,question,answer,sort_order) values ('landscaping','{"en":"Can existing trees be part of the plan?","ar":"هل يمكن دمج الأشجار القائمة في التصميم؟"}'::jsonb,'{"en":"Yes. Established trees can provide structure and shade; their health and root space should guide the layout.","ar":"نعم، فالأشجار القائمة تمنح المكان بنية وظلاً. ويُراعى وضعها الصحي ومساحة جذورها عند التخطيط."}'::jsonb,0);
insert into public.service_faqs(service_slug,question,answer,sort_order) values ('landscaping','{"en":"What if I only want to change one area?","ar":"ماذا لو أردت تغيير جزء واحد فقط؟"}'::jsonb,'{"en":"Identify the area you want to change and how it connects to the rest of the property. Note any paths, trees or seating you want to keep.","ar":"حدّد الجزء الذي تريد تغييره وكيف يتصل ببقية العقار. واذكر الممرات أو الأشجار أو أماكن الجلوس التي تريد الإبقاء عليها."}'::jsonb,1);
insert into public.services(slug,title,summary,detail,scope,image,image_alt,sort_order) values ('plant-and-irrigation','{"en":"Planting & irrigation","ar":"الزراعة والري"}'::jsonb,'{"en":"Plant selection, planting arrangements and watering suited to the site.","ar":"اختيار النباتات وتوزيعها وتحديد أساليب الري الملائمة للموقع."}'::jsonb,'{"en":"Sun exposure, drainage and water needs shape planting choices. Grouping plants with similar water needs can simplify irrigation and make adjustments easier across seasons.","ar":"تؤثر أشعة الشمس وتصريف التربة واحتياجات المياه في اختيار النباتات. ويساعد تجميع النباتات ذات الاحتياجات المتقاربة على تبسيط الري وتعديله بين المواسم."}'::jsonb,'[{"en":"Review sun, exposure and soil drainage.","ar":"مراجعة التعرض للشمس والرياح وتصريف التربة."},{"en":"Choose planting suited to each area.","ar":"اختيار نباتات مناسبة لكل منطقة."},{"en":"Review emitter placement and watering zones.","ar":"مراجعة مواقع النقاطات وتقسيم مناطق الري."}]'::jsonb,'nursery','{"en":"Terracotta pots, seedlings and soil on a nursery workbench","ar":"أصص فخارية وشتلات وتربة على طاولة عمل في مشتل"}'::jsonb,30);
insert into public.service_faqs(service_slug,question,answer,sort_order) values ('plant-and-irrigation','{"en":"Can you work with an existing watering system?","ar":"هل يمكن استخدام نظام الري الحالي؟"}'::jsonb,'{"en":"Include the system type and any dry or wet spots in your inquiry so the scope can include a review.","ar":"اذكر نوع النظام وأي بقع جافة أو شديدة الرطوبة حتى تُدرج مراجعته ضمن نطاق العمل."}'::jsonb,0);
insert into public.service_faqs(service_slug,question,answer,sort_order) values ('plant-and-irrigation','{"en":"What if only one part of my garden is dry?","ar":"ماذا لو كان جزء واحد فقط من حديقتي جافاً؟"}'::jsonb,'{"en":"Mark the dry area, note when it receives sun, and check whether nearby plants on the same watering schedule are also affected.","ar":"حدّد الجزء الجاف ووقت تعرّضه للشمس، ولاحظ ما إذا كانت النباتات المجاورة التي تُروى وفق الجدول نفسه متأثرة أيضاً."}'::jsonb,1);
